				.tooltip("Clan Events")
				.icon(icon)
				.priority(5)
				.panel(panel)
				.build();
		if(!config.sheetId().equals("") && !config.apiKey().equals("")){
			clientToolbar.addNavigation(uiNavigationButton);
		}
	}

